    let contextStr = 'Regular day';
    if (attendanceForm.holiday) contextStr = 'Holiday';
    if (attendanceForm.event) contextStr = 'Event';

    const newSignal = {
      date: attendanceForm.date,
      day: attendanceForm.day,
      expected: Number(attendanceForm.expectedDiners),
      context: contextStr,
      meal: attendanceForm.meal
    };

    fetch(`${API_BASE}/attendance-signals`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify(newSignal)
    })
